    #[tokio::test]
    async fn get_writer_state_aggregates_current_branch() {
        use spindle_core::models::{
            CharacterEmotionalProfileData, CharacterStatePatch, CharacterVoiceProfileData,
            ContentRating, CreateCharacterInput, GetWriterStateInput, SaveSceneDraftInput,
            WriterIntent,
        };

        let (_tmp, svc) = fresh_service().await;

        // Project + 1 character + 1 saved scene on chapter 1.
        let proj = svc
            .create_project(CreateProjectInput {
                name: "Wardens".into(),
                project_type: "novel".into(),
                genre: "fantasy".into(),
                reader_contract: ReaderContract {
                    promise: "Oathbound wardens fail.".into(),
                    style_notes: Vec::new(),
                    boundaries: Vec::new(),
                },
            })
            .await
            .unwrap();

        svc.create_character(CreateCharacterInput {
            project_id: proj.project_id.clone(),
            name: "Mara".into(),
            summary: "Warden of the Ash Gate.".into(),
            role: "protagonist".into(),
            realm: None,
            voice_profile: CharacterVoiceProfileData {
                tone: None,
                vocabulary: Vec::new(),
                sentence_structure: Vec::new(),
                tics: Vec::new(),
                forbidden_words: Vec::new(),
                example_lines: Vec::new(),
                established_in_scene_id: None,
                updated_at: None,
            },
            emotional_profile: CharacterEmotionalProfileData {
                base_emotions: std::collections::BTreeMap::new(),
                suppressed: Vec::new(),
                triggers: Vec::new(),
                defense_mechanisms: Vec::new(),
                flex_range: None,
            },
            initial_state: Some(CharacterStatePatch {
                emotional_state: std::collections::BTreeMap::new(),
                goals: None,
                status: Some(vec!["holding the gate".into()]),
                notes: None,
                source_summary: None,
            }),
        })
        .await
        .unwrap();

        svc.save_scene_draft(SaveSceneDraftInput {
            project_id: proj.project_id.clone(),
            book_number: 1,
            chapter_number: 1,
            chapter_id: None,
            scene_order: 1,
            full_text: "Mara stood at the Ash Gate.".into(),
            summary: "Mara holds the gate".into(),
            content_rating: ContentRating::General,
            tone: Some("grim".into()),
            generation_id: None,
            source_path: None,
            ..Default::default()
        })
        .await
        .unwrap();

        // No branch / cursor / format supplied — defaults exercise the
        // active-branch resolution, cursor-from-last-scene fallback, and
        // markdown budget enforcement together.
        let state = svc
            .get_writer_state(GetWriterStateInput {
                project_id: proj.project_id.clone(),
                branch_id: None,
                at_scene_id: None,
                format: None,
                budget_tokens: None,
                include_subjects: None,
                include_recent_activity: None,
                recent_activity_limit: None,
            })
            .await
            .unwrap();

        assert_eq!(state.current.project.project_id, proj.project_id);
        assert_eq!(state.current.branch.branch_id, proj.branch_id);
        assert!(state.current.branch.is_active);
        let scene = state
            .current
            .scene
            .expect("cursor scene resolves from last scene");
        assert_eq!(scene.book_number, 1);
        assert_eq!(scene.chapter_number, 1);
        assert_eq!(scene.scene_order, 1);
        assert_eq!(state.current.intent, WriterIntent::Drafting);

        // Character snapshot present and includes the initial status patch.
        assert_eq!(state.subjects.len(), 1);
        assert_eq!(state.subjects[0].subject.name, "Mara");
        assert_eq!(
            state.subjects[0].status,
            vec!["holding the gate".to_string()]
        );

        // Bundle summary populated by enforce_writer_state_budget.
        assert!(state.bundle_summary.estimated_tokens > 0);
        assert_eq!(state.bundle_summary.token_budget, Some(8000));
        assert!(
            state
                .bundle_summary
                .included_sections
                .iter()
                .any(|s| s == "current")
        );

        // No scene_source_link rows were created in this fixture, so
        // SourceBridge divergence detection has nothing to report.
        assert!(state.unsynced_local_files.is_empty());
        assert!(state.drift_warnings.is_empty());

        let envelope = svc
            .get_writer_state_envelope(GetWriterStateInput {
                project_id: proj.project_id.clone(),
                branch_id: None,
                at_scene_id: None,
                format: None,
                budget_tokens: None,
                include_subjects: None,
                include_recent_activity: None,
                recent_activity_limit: None,
            })
            .await
            .unwrap();
        assert_eq!(envelope.current.project.project_id, proj.project_id);
        assert!(
            envelope
                .writer_state_markdown
                .as_deref()
                .is_some_and(|markdown| markdown.contains("# Writer state")),
            "public envelope should include markdown when requested/defaulted"
        );
    }

    #[tokio::test]
    async fn migrate_canonical_fact_supersedes_old_fact() {
        use spindle_core::models::{
            CanonicalFactUpgradeSpec, ContentRating, MigrateCanonicalFactInput,
            RegisterCanonicalFactInput, SaveSceneDraftInput,
        };

        let (_tmp, svc) = fresh_service().await;
        let proj = svc
            .create_project(CreateProjectInput {
                name: "Canon".into(),
                project_type: "novel".into(),
                genre: "fantasy".into(),
                reader_contract: ReaderContract {
                    promise: "p".into(),
                    style_notes: Vec::new(),
                    boundaries: Vec::new(),
                },
            })
            .await
            .unwrap();

        let scene = svc
            .save_scene_draft(SaveSceneDraftInput {
                project_id: proj.project_id.clone(),
                book_number: 1,
                chapter_number: 1,
                chapter_id: None,
                scene_order: 1,
                full_text: "A scene.".into(),
                summary: "stage".into(),
                content_rating: ContentRating::General,
                tone: None,
                generation_id: None,
                source_path: None,
                ..Default::default()
            })
            .await
            .unwrap();

        // Seed an untyped canonical fact via register_canonical_fact.
        let untyped = svc
            .register_canonical_fact(RegisterCanonicalFactInput {
                project_id: proj.project_id.clone(),
                scene_id: scene.scene_id.clone(),
                book_number: 1,
                chapter_number: 1,
                fact_type: Some("note".into()),
                key: Some("Kael:gear".into()),
                value: Some("worn cloak".into()),
                context: None,
                subject_table: None,
                subject_id: None,
                predicate: None,
                value_kind: None,
                value_text: None,
                value_number: None,
                value_unit: None,
                value_json: None,
                aliases: Vec::new(),
                scope: None,
                valid_from: None,
                valid_until: None,
                legacy_untyped: Some(true),
                supersedes_fact_id: None,
                secrecy: None,
            })
            .await
            .unwrap();

        let migrated = svc
            .migrate_canonical_fact(MigrateCanonicalFactInput {
                fact_id: untyped.canonical_fact_id.clone(),
                upgrade_spec: CanonicalFactUpgradeSpec {
                    subject_table: "character".into(),
                    subject_id: Some("character:kael".into()),
                    predicate: "gear".into(),
                    value_kind: "string".into(),
                    value_text: Some("worn cloak".into()),
                    value_number: None,
                    value_unit: None,
                    value_json: None,
                    aliases: vec!["cloak".into()],
                    scope: None,
                    valid_from: None,
                    valid_until: None,
                },
            })
            .await
            .unwrap();

        assert_eq!(migrated.superseded_fact_id, untyped.canonical_fact_id);
        assert_ne!(
            migrated.canonical_fact_id, untyped.canonical_fact_id,
            "migrate must create a new fact id"
        );

        // The old fact is now superseded by the new typed fact.
        let old = svc
            .repository()
            .get_canonical_fact(&untyped.canonical_fact_id)
            .await
            .unwrap();
        assert_eq!(
            old.superseded_by.as_deref(),
            Some(migrated.canonical_fact_id.as_str())
        );
    }

    #[tokio::test]
    async fn preflight_book_export_flags_blocking_and_warning_issues() {
        use spindle_core::models::{
            ContentRating, ExportIssueSeverity, PreflightBookExportInput, SaveSceneDraftInput,
        };

        let (_tmp, svc) = fresh_service().await;
        let proj = svc
            .create_project(CreateProjectInput {
                name: "Export Drill".into(),
                project_type: "novel".into(),
                genre: "fantasy".into(),
                reader_contract: ReaderContract {
                    promise: "p".into(),
                    style_notes: Vec::new(),
                    boundaries: Vec::new(),
                },
            })
            .await
            .unwrap();

        // Save a non-empty scene in chapter 1 — no blocking issues, but
        // chapter title was never set so we expect a warning.
        svc.save_scene_draft(SaveSceneDraftInput {
            project_id: proj.project_id.clone(),
            book_number: 1,
            chapter_number: 1,
            chapter_id: None,
            scene_order: 1,
            full_text: "Real prose.".into(),
            summary: "stage".into(),
            content_rating: ContentRating::General,
            tone: None,
            generation_id: None,
            source_path: None,
            ..Default::default()
        })
        .await
        .unwrap();

        let out = svc
            .preflight_book_export(PreflightBookExportInput {
                project_id: proj.project_id.clone(),
                book_number: Some(1),
                start_chapter_number: None,
                end_chapter_number: None,
            })
            .await
            .unwrap();

        assert!(out.issues.iter().any(|i| i.code == "chapter_missing_title"
            && matches!(i.severity, ExportIssueSeverity::Warning)));
        assert!(
            out.issues
                .iter()
                .all(|i| i.code != "chapter_without_scenes"),
            "chapter 1 has a scene, must not be flagged blocking"
        );

        // Half-open chapter range → error.
        let err = svc
            .preflight_book_export(PreflightBookExportInput {
                project_id: proj.project_id.clone(),
                book_number: Some(1),
                start_chapter_number: Some(1),
                end_chapter_number: None,
            })
            .await
            .unwrap_err();
        assert!(err.to_string().contains("requires both"));
    }

    /// Variant of `fresh_service` whose data dir is a real `.spindle`
    /// directory under a tempdir, so `artifacts_dir_for_data_dir` resolves to
    /// the workspace root (the tempdir) exactly as it does in a real project.
    async fn fresh_service_workspace() -> (TempDir, SqliteSpindleService) {
        let tmp = TempDir::new().unwrap();
        let data_dir = tmp.path().join(".spindle");
        std::fs::create_dir_all(&data_dir).unwrap();
        let pool = SqlitePool::open(&data_dir.join("spindle.db"))
            .await
            .unwrap();
        let repo = Repository::new(pool, data_dir);
        (tmp, SqliteSpindleService::new(repo))
    }

    #[tokio::test]
    async fn compile_manuscript_assembles_headings_prose_and_flags_undrafted_scenes() {
        use spindle_core::models::{
            CompileManuscriptInput, ContentRating, PlanChapterInput, PlanChapterSceneInput,
            SaveSceneDraftInput, UpdateEntityInput,
        };

        let (_tmp, svc) = fresh_service().await;
        let proj = svc
            .create_project(CreateProjectInput {
                name: "Read So Far".into(),
                project_type: "novel".into(),
                genre: "fantasy".into(),
                reader_contract: ReaderContract {
                    promise: "p".into(),
                    style_notes: Vec::new(),
                    boundaries: Vec::new(),
                },
            })
            .await
            .unwrap();

        // Chapter 1: two committed scenes, no plan.
        for (order, text) in [
            (1, "Ch1 scene1 opens the tale."),
            (2, "Ch1 scene2 raises stakes."),
        ] {
            svc.save_scene_draft(SaveSceneDraftInput {
                project_id: proj.project_id.clone(),
                book_number: 1,
                chapter_number: 1,
                chapter_id: None,
                scene_order: order,
                full_text: text.into(),
                summary: "s".into(),
                content_rating: ContentRating::General,
                tone: None,
                generation_id: None,
                source_path: None,
                ..Default::default()
            })
            .await
            .unwrap();
        }

        // Give chapter 1 a title so the heading renders it.
        let ch1 = svc
            .repository
            .find_chapter_by_number(&proj.project_id, 1, 1)
            .await
            .unwrap()
            .unwrap();
        svc.update_entity(UpdateEntityInput {
            entity_type: "chapter".into(),
            entity_id: ch1.id.clone(),
            changes: serde_json::json!({ "title": "The Gate" }),
        })
        .await
        .unwrap();

        // Chapter 2: plan spine of 2 scenes; only scene 2.1 persisted.
        svc.plan_chapter(PlanChapterInput {
            project_id: proj.project_id.clone(),
            book_number: 1,
            chapter_number: 2,
            pov_character_id: None,
            synopsis: "The reckoning".into(),
            target_theme_ids: Vec::new(),
            target_conflict_ids: Vec::new(),
            target_plot_line_ids: Vec::new(),
            scenes: vec![
                PlanChapterSceneInput {
                    scene_order: 1,
                    summary: "drafted".into(),
                    purpose: "establishing".into(),
                    ..Default::default()
                },
                PlanChapterSceneInput {
                    scene_order: 2,
                    summary: "undrafted".into(),
                    purpose: "complication".into(),
                    ..Default::default()
                },
            ],
        })
        .await
        .unwrap();
        svc.save_scene_draft(SaveSceneDraftInput {
            project_id: proj.project_id.clone(),
            book_number: 1,
            chapter_number: 2,
            chapter_id: None,
            scene_order: 1,
            full_text: "Ch2 scene1 lands the blow.".into(),
            summary: "s".into(),
            content_rating: ContentRating::General,
            tone: None,
            generation_id: None,
            source_path: None,
            ..Default::default()
        })
        .await
        .unwrap();

        let out = svc
            .compile_manuscript(CompileManuscriptInput {
                project_id: proj.project_id.clone(),
                book_number: 1,
                start_chapter: None,
                end_chapter: None,
                write_to_workspace: false,
            })
            .await
            .unwrap();

        // Ordered headings and prose bodies for chapter 1 (title included).
        assert!(out.markdown.contains("## Chapter 1: The Gate"));
        assert!(out.markdown.contains("### Scene 1.1"));
        assert!(out.markdown.contains("Ch1 scene1 opens the tale."));
        assert!(out.markdown.contains("### Scene 1.2"));
        assert!(out.markdown.contains("Ch1 scene2 raises stakes."));
        assert!(out.markdown.contains("## Chapter 2"));
        assert!(out.markdown.contains("### Scene 2.1"));
        assert!(out.markdown.contains("Ch2 scene1 lands the blow."));
        // Undrafted 2.2 renders an explicit placeholder, never silently omitted.
        assert!(out.markdown.contains("> [scene 2.2 not yet drafted]"));

        // Chapter 1 precedes chapter 2 in the assembled document.
        let ch1 = out.markdown.find("## Chapter 1").unwrap();
        let ch2 = out.markdown.find("## Chapter 2").unwrap();
        assert!(ch1 < ch2, "chapters must be assembled in order");

        assert_eq!(out.missing_scenes, vec!["2.2".to_string()]);
        assert_eq!(out.scene_count, 3);
        assert!(out.word_count > 0);
        assert!(out.artifact_path.is_none());
    }

