        let calendar = CalendarDef {
            days_per_week: 7,
            hours_per_day: 24,
            week_day_names: Vec::new(),
            months: Vec::new(),
            days_per_year: 365,
            epoch_label: None,
        };
        repo.upsert_project_calendar(&proj.project_id, &calendar)
            .await
