    #[tokio::test]
    async fn scene_context_surfaces_semantic_references() {
        use crate::ai::SearchDocument;
        use spindle_core::models::{
            CharacterEmotionalProfileData, CharacterVoiceProfileData, ContextFormat,
            CreateCharacterInput, CreateLocationInput, GetSceneContextInput, WorldStateInput,
        };

        let (_tmp, svc) = fresh_service().await;
        let proj = svc
            .create_project(CreateProjectInput {
                name: "semrefs".into(),
                project_type: "novel".into(),
                genre: "fantasy".into(),
                reader_contract: ReaderContract {
                    promise: "Oathbound wardens hold the line.".into(),
                    style_notes: Vec::new(),
                    boundaries: Vec::new(),
                },
            })
            .await
            .unwrap();

        let mara = svc
            .create_character(CreateCharacterInput {
                project_id: proj.project_id.clone(),
                name: "Mara".into(),
                summary: "Oathbound warden who holds the Ash Gate against the dark.".into(),
                role: "protagonist".into(),
                realm: None,
                voice_profile: CharacterVoiceProfileData {
                    tone: None,
                    vocabulary: Vec::new(),
                    sentence_structure: Vec::new(),
                    tics: Vec::new(),
                    forbidden_words: Vec::new(),
                    example_lines: Vec::new(),
                    established_in_scene_id: None,
                    updated_at: None,
                },
                emotional_profile: CharacterEmotionalProfileData {
                    base_emotions: std::collections::BTreeMap::new(),
                    suppressed: Vec::new(),
                    triggers: Vec::new(),
                    defense_mechanisms: Vec::new(),
                    flex_range: None,
                },
                initial_state: None,
            })
            .await
            .unwrap();

        let gate = svc
            .create_location(CreateLocationInput {
                project_id: proj.project_id.clone(),
                name: "Ash Gate".into(),
                kind: "fortress".into(),
                realm: None,
                summary: "A blackened wall holding back the dark.".into(),
                initial_state: WorldStateInput::default(),
            })
            .await
            .unwrap();

        let branch = svc
            .repository()
            .get_active_branch(&proj.project_id)
            .await
            .unwrap();

        // Seed three embeddings on the active branch:
        //  - Mara herself (must be EXCLUDED — she's a present-scene entity)
        //  - a topically-overlapping faction (must SURFACE — distant but related)
        //  - an unrelated scribe (allowed, but ranked far)
        let faction_id = "world_rule:oath-wardens";
        let scribe_id = "character:aldric-scribe";
        for (id, doc) in [
            (
                mara.character_id.as_str(),
                SearchDocument {
                    entity_table: "character".into(),
                    title: "Mara".into(),
                    excerpt: "oath warden".into(),
                    content: "Mara, oathbound warden, holds the Ash Gate against the dark.".into(),
                },
            ),
            (
                faction_id,
                SearchDocument {
                    entity_table: "world_rule".into(),
                    title: "Oath Wardens".into(),
                    excerpt: "the order that holds the gate".into(),
                    content:
                        "The Oath Wardens are oathbound to hold the Ash Gate against the dark."
                            .into(),
                },
            ),
            (
                scribe_id,
                SearchDocument {
                    entity_table: "character".into(),
                    title: "Aldric".into(),
                    excerpt: "scribe".into(),
                    content: "Aldric copies old maps by candlelight; ink stains his cuffs.".into(),
                },
            ),
        ] {
            svc.repository()
                .upsert_search_embedding_document(&proj.project_id, &branch.id, id, &doc)
                .await
                .unwrap();
        }

        let ctx = svc
            .get_scene_context(GetSceneContextInput {
                project_id: proj.project_id.clone(),
                book_number: 1,
                chapter_number: 1,
                chapter_id: None,
                scene_order: 1,
                character_ids: vec![mara.character_id.clone()],
                max_character_count: None,
                location_id: gate.location_id.clone(),
                format: Some(ContextFormat::Json),
                budget_tokens: None,
                token_budget: None,
                sections: Some(vec!["semantic_references".into()]),
            })
            .await
            .unwrap();

        let refs = &ctx.novel.semantic_references;
        assert!(
            refs.iter().any(|r| r.entity_id == faction_id),
            "topically-related distant canon should surface: {refs:?}"
        );
        assert!(
            !refs.iter().any(|r| r.entity_id == mara.character_id),
            "a present-scene character must be excluded from recall: {refs:?}"
        );
        assert!(
            !refs.iter().any(|r| r.entity_id == gate.location_id),
            "the present location must be excluded from recall: {refs:?}"
        );
        // The overlapping faction must outrank the unrelated scribe.
        let faction_score = refs
            .iter()
            .find(|r| r.entity_id == faction_id)
            .map(|r| r.score)
            .expect("faction must be present");
        if let Some(scribe) = refs.iter().find(|r| r.entity_id == scribe_id) {
            assert!(
                faction_score > scribe.score,
                "related canon must outrank unrelated canon: {refs:?}"
            );
        }
    }

    #[tokio::test]
    async fn save_summary_maintains_book_digest_idempotently() {
        use spindle_core::models::SaveSummaryInput;

        let (_tmp, svc) = fresh_service().await;
        let proj = svc
            .create_project(CreateProjectInput {
                name: "digest".into(),
                project_type: "novel".into(),
                genre: "fantasy".into(),
                reader_contract: ReaderContract {
                    promise: "p".into(),
                    style_notes: Vec::new(),
                    boundaries: Vec::new(),
                },
            })
            .await
            .unwrap();
        let repo = svc.repository();
        let branch = repo.get_active_branch(&proj.project_id).await.unwrap();
        let mk = |chapter: i32, summary: &str| SaveSummaryInput {
            project_id: proj.project_id.clone(),
            book_number: 1,
            chapter_number: chapter,
            entity_type: None,
            entity_id: None,
            summary: summary.into(),
            key_events: Vec::new(),
            character_changes: Vec::new(),
            relationship_shifts: Vec::new(),
            arc_advances: Vec::new(),
            promise_events: Vec::new(),
        };

        repo.save_summary(&mk(1, "Mara reaches the Ash Gate"))
            .await
            .unwrap();
        repo.save_summary(&mk(2, "Mara duels the warden"))
            .await
            .unwrap();

        let digests = repo
            .list_book_digests_by_project_and_branch(&proj.project_id, &branch.id)
            .await
            .unwrap();
        assert_eq!(digests.len(), 1, "one digest per book");
        assert_eq!(digests[0].book_number, 1);
        assert_eq!(digests[0].last_chapter_covered, 2);
        assert!(digests[0].synopsis.contains("Ash Gate"));
        assert!(digests[0].synopsis.contains("duels the warden"));

        // Re-saving a chapter must NOT double-count (idempotent re-derive).
        repo.save_summary(&mk(2, "Mara duels the warden"))
            .await
            .unwrap();
        let digests = repo
            .list_book_digests_by_project_and_branch(&proj.project_id, &branch.id)
            .await
            .unwrap();
        assert_eq!(digests.len(), 1);
        assert_eq!(digests[0].last_chapter_covered, 2);
        assert_eq!(
            digests[0].synopsis.matches("duels the warden").count(),
            1,
            "chapter must appear exactly once after re-save"
        );
    }

    #[tokio::test]
    async fn save_summary_populates_open_threads_from_unresolved_threads() {
        use spindle_core::models::{
            CreateConflictInput, CreateNarrativePromiseInput, CreatePlotLineInput,
            SaveSummaryInput, StatedConsequence, StoryPlacement,
        };

        let (_tmp, svc) = fresh_service().await;
        let proj = svc
            .create_project(CreateProjectInput {
                name: "threads".into(),
                project_type: "novel".into(),
                genre: "fantasy".into(),
                reader_contract: ReaderContract {
                    promise: "p".into(),
                    style_notes: Vec::new(),
                    boundaries: Vec::new(),
                },
            })
            .await
            .unwrap();

        // An active promise (not paid_off/abandoned) with placements.
        let promise = svc
            .create_narrative_promise(CreateNarrativePromiseInput {
                project_id: proj.project_id.clone(),
                promise_type: "setup".into(),
                description: "the buried crown will be reclaimed".into(),
                planted_at: StoryPlacement {
                    book_number: 1,
                    chapter_number: 1,
                    scene_order: Some(0),
                    note: None,
                },
                planned_payoff: Some(StoryPlacement {
                    book_number: 1,
                    chapter_number: 10,
                    scene_order: Some(0),
                    note: None,
                }),
                notes: Vec::new(),
            })
            .await
            .unwrap();
        svc.update_promise_status(spindle_core::models::UpdatePromiseStatusInput {
            narrative_promise_id: promise.narrative_promise_id.clone(),
            status: "active".into(),
            note: None,
        })
        .await
        .unwrap();

        // A conflict with an undelivered stated consequence.
        svc.create_conflict(CreateConflictInput {
            project_id: proj.project_id.clone(),
            name: "Siege of the Ash Gate".into(),
            conflict_type: "external".into(),
            stakes: "the last free city".into(),
            escalation_stages: Vec::new(),
            expected_total_cycles: None,
            try_fail_cycles: Vec::new(),
            stated_consequences: vec![StatedConsequence {
                description: "the wall will crack".into(),
                stated_at: None,
                must_demonstrate_by: None,
                delivered: false,
            }],
        })
        .await
        .unwrap();

        // A plot line not yet complete.
        svc.create_plot_line(CreatePlotLineInput {
            project_id: proj.project_id.clone(),
            name: "The Reclamation".into(),
            plot_type: "main".into(),
            summary: "the rightful heir returns".into(),
            status: Some("developing".into()),
            convergence_points: Vec::new(),
            connected_conflict_ids: Vec::new(),
            connected_theme_ids: Vec::new(),
        })
        .await
        .unwrap();

        let repo = svc.repository();
        let branch = repo.get_active_branch(&proj.project_id).await.unwrap();
        repo.save_summary(&SaveSummaryInput {
            project_id: proj.project_id.clone(),
            book_number: 1,
            chapter_number: 1,
            entity_type: None,
            entity_id: None,
            summary: "The heir flees the burning capital".into(),
            key_events: Vec::new(),
            character_changes: Vec::new(),
            relationship_shifts: Vec::new(),
            arc_advances: Vec::new(),
            promise_events: Vec::new(),
        })
        .await
        .unwrap();

        let digests = repo
            .list_book_digests_by_project_and_branch(&proj.project_id, &branch.id)
            .await
            .unwrap();
        assert_eq!(digests.len(), 1);
        let threads = &digests[0].open_threads;
        assert!(!threads.is_empty(), "open threads persisted: {threads:?}");
        assert!(
            threads
                .iter()
                .any(|t| t.contains("the buried crown will be reclaimed")),
            "promise carried into open threads: {threads:?}"
        );
        assert!(
            threads.iter().any(|t| t.contains("Siege of the Ash Gate")),
            "conflict carried into open threads: {threads:?}"
        );
        assert!(
            threads.iter().any(|t| t.contains("The Reclamation")),
            "plot line carried into open threads: {threads:?}"
        );
    }

